select DISTINCT tma.id, tma.user_id, tma.avatar_url, tma.phone, tma.nike_name, tma.first_login_time, tmae.last_deal_time, tmae.integral, tmae.consume_num, tmae.consume_totle_money, tmae.community_type, tmae.shop_user_id, tmae.supply_bonus, tmae.rebate_bonus, member.member_register_time, a.nike_name as first_nick_name, a.phone as first_phone, (select count(*) from t_member_balance_record r where r.shop_user_id = (select shop_user_id from t_mini_account_extends s where s.user_id = tma.user_id) and r.deal_type = 4 and r.is_deleted = 0 and r.shop_id = #{paramMap.shopId}) as order_count, (select ifnull(sum(r.use_balance),0) from t_member_balance_record r where r.shop_user_id = (select shop_user_id from t_mini_account_extends s where s.user_id = tma.user_id) and r.deal_type = 4 and r.is_deleted = 0 and r.shop_id = #{paramMap.shopId}) as first_distribution_amount from t_mini_account AS tma left join (select s.shop_user_id, acc.nike_name, acc.phone from t_mini_account_extends s left join t_mini_account acc on s.user_id = acc.user_id where s.is_deleted = 0 and acc.is_deleted = 0) as a on a.shop_user_id = tma.first_user_id left join t_mini_account_extends AS tmae on tmae.user_id = tma.user_id LEFT JOIN (SELECT ttmi.user_id, ANY_VALUE ( ttmi.member_register_time ) AS member_register_time, ANY_VALUE ( ttmi.member_number ) AS member_number, ANY_VALUE ( ttmi.member_card_info_id ) AS member_card_info_id, ANY_VALUE ( tmci.rank_code ) AS rank_code FROM t_member_info ttmi left join t_member_card_info as tmci on tmci.id = ttmi.member_card_info_id WHERE ttmi.state = 1 AND ttmi.is_deleted = 0 AND ttmi.member_expire_time > sysdate() GROUP BY user_id ) AS member ON member.user_id = tmae.shop_user_id
tmae.is_blacklist = 0 and tmae.shop_id = #{paramMap.shopId} and tma.whether_authorization = 1
and tmae.shop_user_id in (SELECT user_id FROM t_mini_account_tag_group where tag_id = #{paramMap.tagId} and is_deleted = 0)
and tma.nike_name like #{paramMap.nikeName}
and tmae.last_deal_time >= #{paramMap.orderSuccessStartTime}
and tmae.last_deal_time <= #{paramMap.orderSuccessEndTime}
and member.member_register_time >= #{paramMap.becomeMemberStartTime}
and member.member_register_time <= #{paramMap.becomeMemberEndTime}
and member.member_number like concat('%', #{paramMap.memberNumber}, '%')
and member.rank_code = #{paramMap.rankCode}
order by
tmae.consume_totle_money desc,tma.id
tmae.consume_totle_money asc
member.member_register_time desc
member.member_register_time asc
order by tmae.shop_user_id desc

SELECT extends.shop_id AS shopId, extends.mobile AS phone, extends.first_user_id AS firstUserId, extends.user_id AS userId, extends.avatar AS avatarUrl, extends.nickname AS nikeName, extends.first_login_time AS firstLoginTime, extends.last_deal_time AS lastDealTime, extends.integral AS integral, extends.consume_num AS consumeNum, extends.consume_totle_money AS consumeTotleMoney, extends.community_type AS communityType, extends.shop_user_id AS shopUserId, extends.supply_bonus AS supplyBonus, extends.rebate_bonus AS rebateBonus, memberInfo.member_register_time as memberRegisterTime FROM t_mini_account_extends AS extends LEFT JOIN t_member_info AS memberInfo ON extends.user_id = memberInfo.user_id AND memberInfo.is_deleted = 0 AND memberInfo.state = 1 AND memberInfo.member_expire_time > SYSDATE() WHERE extends.is_blacklist = 0 AND extends.shop_id = #{param.shopId}
AND EXISTS ( SELECT tagGroup.id FROM t_mini_account_tag_group AS tagGroup WHERE tagGroup.user_id = shop.shop_user_id AND tagGroup.tag_id = #{param.tagId} AND tagGroup.is_deleted = 0 )
AND LOCATE( #{param.nikeName}, extends.nickname ) > 0
AND extends.last_deal_time >= #{param.orderSuccessStartTime}
AND extends.last_deal_time <= #{param.orderSuccessEndTime}
AND memberInfo.member_register_time >= #{param.becomeMemberStartTime}
AND memberInfo.member_register_time <= #{param.becomeMemberEndTime}
AND LOCATE(#{param.memberNumber},memberInfo.member_number)
AND EXISTS( SELECT * FROM t_member_card_info AS memberCardInfo WHERE memberCardInfo.id = memberInfo.member_card_info_id AND memberCardInfo.rank_code = #{param.rankCode} AND memberCardInfo.is_deleted=0)
ORDER BY extends.consume_totle_money DESC
ORDER BY extends.consume_totle_money ASC
ORDER BY memberInfo.member_register_time DESC
ORDER BY memberInfo.member_register_time ASC
ORDER BY extends.shop_user_id DESC

select integral
from t_mini_account_extends t
where t.is_deleted = 0

    AND t.shop_id = #{shopId}


    AND t.shop_user_id = #{shopUserId}

