set t.supply_bonus = #{amount}
where t.is_deleted = 0
  and t.shop_user_id = #{userId}

update t_mini_account_extends t
set t.rebate_bonus = #{amount}
where t.is_deleted = 0
  and t.shop_user_id = #{userId}

